-- Tickets 12 + 13: feature flags, maintenance, minimum build, announcements, versioned Balance Config,
-- server-side config validation (JSON Schema generated from the zod schema) and the audit log.

-- ---------- audit log (written by triggers only; nobody can edit it) ----------
create table public.audit_log (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  actor uuid,
  action text not null,
  target text not null,
  detail jsonb not null default '{}'::jsonb
);
alter table public.audit_log enable row level security;
revoke all on public.audit_log from anon, authenticated;

create or replace function public.audit_trigger()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.audit_log (actor, action, target, detail)
  values (auth.uid(), lower(tg_op), tg_table_name,
          jsonb_build_object('old', case when tg_op <> 'INSERT' then to_jsonb(old) end, 'new', case when tg_op <> 'DELETE' then to_jsonb(new) end));
  return coalesce(new, old);
end $$;

create or replace function public.audit_log_immutable()
returns trigger language plpgsql as $$ begin raise exception 'AUDIT_LOG_IS_APPEND_ONLY'; end $$;
create trigger audit_log_no_update before update or delete on public.audit_log for each row execute function public.audit_log_immutable();

create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
$$;

create or replace function public.assert_admin()
returns uuid language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'NOT_ADMIN' using errcode = '42501'; end if;
  return auth.uid();
end $$;

-- ---------- feature flags ----------
create table public.feature_flags (
  key text primary key,
  value jsonb not null,
  description text not null default '',
  updated_at timestamptz not null default now()
);
alter table public.feature_flags enable row level security;
revoke all on public.feature_flags from anon, authenticated;
grant select on public.feature_flags to anon, authenticated;
create policy flags_read on public.feature_flags for select to anon, authenticated using (true);
insert into public.feature_flags (key, value, description) values
  ('coop', 'true'::jsonb, 'Co-op rooms enabled'),
  ('scoreSubmit', 'true'::jsonb, 'Leaderboard submissions enabled (Runs still pay Gold)'),
  ('bloodMoon', 'true'::jsonb, 'Blood Moon event enabled'),
  ('dragon', 'true'::jsonb, 'Inferno Dragon enabled'),
  ('rival', 'true'::jsonb, 'Shadow Rival enabled'),
  ('maintenance', 'false'::jsonb, 'Maintenance mode: online features paused'),
  ('minClientBuild', '0'::jsonb, 'Clients older than this build must reload');
create trigger feature_flags_audit after insert or update or delete on public.feature_flags for each row execute function public.audit_trigger();

create or replace function public.flag(p_key text)
returns jsonb language sql stable security definer set search_path = '' as $$
  select value from public.feature_flags where key = p_key
$$;

-- ---------- announcements ----------
create table public.announcements (
  id bigint generated always as identity primary key,
  title_th text not null default '', title_en text not null default '',
  body_th text not null default '', body_en text not null default '',
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.announcements enable row level security;
revoke all on public.announcements from anon, authenticated;
grant select on public.announcements to anon, authenticated;
create policy announcements_read_active on public.announcements for select to anon, authenticated
  using (starts_at <= now() and (ends_at is null or ends_at > now()));
create trigger announcements_audit after insert or update or delete on public.announcements for each row execute function public.audit_trigger();

-- ---------- one cheap call at launch and at every Stage start (REST, no Realtime) ----------
create or replace function public.get_live_state()
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'flags', coalesce((select jsonb_object_agg(key, value) from public.feature_flags), '{}'::jsonb),
    'configVersion', public.current_config_version(),
    'announcements', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'title', jsonb_build_object('th', title_th, 'en', title_en),
        'body', jsonb_build_object('th', body_th, 'en', body_en), 'endsAt', ends_at) order by starts_at desc)
      from public.announcements where starts_at <= now() and (ends_at is null or ends_at > now())), '[]'::jsonb),
    'serverTime', now())
$$;

-- Maintenance pauses every gameplay RPC (solo offline play keeps working on the client).
create or replace function public.assert_session()
returns uuid language plpgsql stable security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  active uuid;
begin
  if uid is null then
    raise exception 'NOT_SIGNED_IN' using errcode = '28000';
  end if;
  if coalesce((public.flag('maintenance'))::boolean, false) and not public.is_admin() then
    raise exception 'MAINTENANCE' using errcode = '57P01';
  end if;
  select p.active_session_id into active from public.profiles p where p.id = uid;
  if active is null or active is distinct from public.jwt_session_id() then
    raise exception 'SESSION_REPLACED' using errcode = 'P0001', hint = 'The account was opened on another device.';
  end if;
  return uid;
end $$;
revoke all on function public.assert_session() from public, anon, authenticated;

-- Score submission can be switched off: Runs still pay Gold but do not rank.
create or replace function public.record_leaderboard(p_run uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  r public.runs;
  season int;
begin
  if not coalesce((public.flag('scoreSubmit'))::boolean, true) then return; end if;
  select * into r from public.runs where id = p_run;
  if r.id is null or r.score is null or r.status not in ('submitted', 'verified') then return; end if;
  if exists (select 1 from public.profiles where id = r.user_id and banned_until > now()) then return; end if;
  season := public.active_season(r.world);
  -- a Run that began in an earlier Season (e.g. suspended across the change) finishes unranked
  if r.season_id is not null and r.season_id is distinct from season then return; end if;
  if r.mode = 'solo' then
    perform public.upsert_board(r.world, season, 'solo', r, true);
    perform public.upsert_board(r.world, 0, 'alltime', r, true);
    -- a Run that went on into Endless also lands on the Endless board with its Endless score
    if coalesce(r.endless_score, 0) > 0 then
      r.score := r.endless_score;
      perform public.upsert_board(r.world, season, 'endless', r, true);
    end if;
  elsif r.mode = 'coop' then
    perform public.upsert_board(r.world, season, 'coop', r, false);
  elsif r.mode = 'endless' then
    perform public.upsert_board(r.world, season, 'endless', r, true);
  end if;
end $$;
revoke all on function public.record_leaderboard(uuid) from public, anon, authenticated;

